add_filter( 'woocommerce_default_address_fields', 'perfectpixel_optional_postcode', 9999 );
add_filter( 'woocommerce_get_country_locale', 'perfectpixel_optional_postcode_locale', 9999 );

function perfectpixel_optional_postcode( $fields ) {
	if ( isset( $fields['postcode'] ) ) {
		$fields['postcode']['required'] = false;
	}
	return $fields;
}

// Some countries mark the postcode as required in their own locale settings.
function perfectpixel_optional_postcode_locale( $locale ) {
	foreach ( $locale as $country => $fields ) {
		if ( isset( $fields['postcode'] ) ) {
			$locale[ $country ]['postcode']['required'] = false;
		}
	}
	return $locale;
}
